END;';
EXEC sys.sp_executesql N'CREATE PROCEDURE dbo.usp_update_test_supplier_contact
 @request_id nvarchar(max),@expected_revision nvarchar(max),@phone nvarchar(max),@city nvarchar(max),@country nvarchar(max),@payload_json nvarchar(max),@payload_hash nvarchar(max),@actor_id bigint
WITH EXECUTE AS OWNER AS BEGIN
SET NOCOUNT ON; SET XACT_ABORT ON; IF @@TRANCOUNT=0 OR NOT EXISTS(SELECT 1 FROM sys.dm_exec_sessions WHERE session_id=@@SPID AND transaction_isolation_level=4) THROW 51077,''TEST_SUPPLIER_CONTACT_TRANSACTION_REQUIRED'',1;
DECLARE @lock int; EXEC @lock=sys.sp_getapplock @Resource=N''MELISA-TEST-V70-SALES'',@LockMode=N''Exclusive'',@LockOwner=N''Transaction'',@LockTimeout=15000;
IF @lock<0 THROW 51077,''TEST_SUPPLIER_CONTACT_LOCK_REQUIRED'',1;
IF DB_NAME()<>N''MELISA_ERP_SIRKET_TEST_20260929_01'' OR CONVERT(nvarchar(128),SERVERPROPERTY(''ServerName''))<>N''Semih\MELISADEV'' THROW 51076,''SUPPLIER_CARD_TARGET_UNAVAILABLE'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.runs WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND status=N''COMMITTED'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'') THROW 51076,''SUPPLIER_CARD_SOURCE_UNAVAILABLE'',1;
IF (SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'')<>''9AE41CA1AB25EE165019AD04DBD9A6FB4E5B7190F027E0A07A87FB03D698379E'' THROW 51076,''SUPPLIER_CARD_GUARD_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' AND is_disabled=0 AND OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger'')=1)<>37 THROW 51076,''SUPPLIER_CARD_QUARANTINE_UNAVAILABLE'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_manifest WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'' AND sealed=1 AND seal_hash=''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' AND source_rows=176 AND native_holds=172 AND not_present=4) THROW 51076,''SUPPLIER_CARD_QUARANTINE_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds)<>176 OR (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WHERE native_id IS NOT NULL)<>172 OR (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WHERE native_id IS NULL)<>4 OR EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT h.entity,h.source_key,h.source_id,h.source_company,h.source_code,h.source_name,h.native_id,h.native_entity_id,h.native_source_key,h.native_code,h.native_name,h.status,h.reasons_json,h.binding_basis FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2)<>h.row_hash) THROW 51076,''SUPPLIER_CARD_QUARANTINE_BINDING_DRIFT'',1;
IF LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT h.source_key,h.row_hash FROM erp_migration.operation_quarantine_holds h ORDER BY h.source_key FOR JSON PATH)),2))<>''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' THROW 51076,''SUPPLIER_CARD_QUARANTINE_BINDING_DRIFT'',1;
IF COALESCE(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_read_customer_cards''))),2),'''')<>''7FE6BEE7728312D666FF3B68151CA60A08B84E4A6D5B33B36F300A48381E6C8E'' THROW 51076,''SUPPLIER_CARD_C06_READER_DRIFT'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_batch_guard_manifest)<>15 OR EXISTS(SELECT 1 FROM dbo.test_purchase_batch_guard_manifest m LEFT JOIN sys.triggers t ON t.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE t.object_id IS NULL OR t.is_disabled=1 OR m.after_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(t.object_id)),2)) THROW 51076,''SUPPLIER_CARD_LEGACY_GUARD_DRIFT'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_fx_guard_manifest)<>17 OR EXISTS(SELECT 1 FROM dbo.test_purchase_fx_guard_manifest m LEFT JOIN sys.objects o ON o.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE o.object_id IS NULL OR m.definition_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(o.object_id)),2) OR (o.type=N''TR'' AND COALESCE(OBJECTPROPERTY(o.object_id,''ExecIsTriggerDisabled''),1)<>0)) THROW 51076,''SUPPLIER_CARD_FX_GUARD_DRIFT'',1;
IF (SELECT COUNT(*) FROM erp_migration.records WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND entity IN(N''parties'',N''accounts'') AND JSON_VALUE(payload_json,''$.role'')=N''supplier'')<>998 OR
(SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(entity,N''|'',source_key,N''|'',payload_hash,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',payload_json),2))),N'';'') WITHIN GROUP(ORDER BY entity,source_key)),2) FROM erp_migration.records WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND entity IN(N''parties'',N''accounts'') AND JSON_VALUE(payload_json,''$.role'')=N''supplier'')<>''59A82329B54B3B08FF5A1AF23B1AC2ED4322ADC2785772604558F1F32BFB8644'' THROW 51076,''SUPPLIER_CARD_STAGE_UNAVAILABLE'',1;
IF COALESCE(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_read_supplier_cards''))),2),'''')<>''D750DDCD6B3F4AEDBDC9A38C5347DED081961A6018505559D2F7D50014404C0B'' THROW 51077,''TEST_SUPPLIER_CONTACT_READER_DRIFT'',1;
IF NOT EXISTS(SELECT 1 FROM dbo.suppliers s WHERE s.id=13373 AND s.supplier_code=N''TEST-DAILY-PUR-S'' AND s.name=N''TEST GÜNLÜK ALIŞ İADE TEDARİKÇİ'' AND s.currency_code=N''TRY'' AND s.is_active=1 AND s.is_deleted=0 AND s.purchase_discount_rate=0 AND s.source_record_key IS NULL AND s.migration_run_id IS NULL AND s.source_payload_hash IS NULL AND s.source_payload_json IS NULL AND s.source_document_key IS NULL AND s.original_document_date IS NULL AND s.party_entity_id IS NULL AND s.source_notes IS NULL AND s.TELEFON1 IS NULL AND s.TELEFON2 IS NULL AND s.TELEFON3 IS NULL AND s.ADRESPOSTA IS NULL AND s.ADRESFATURA IS NULL AND s.ADRESSEVK IS NULL) OR EXISTS(SELECT 1 FROM dbo.party_source_links WHERE supplier_id=13373) OR EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds WHERE entity=N''supplier'' AND native_id=13373) THROW 51077,''TEST_SUPPLIER_CONTACT_FIXTURE_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM dbo.test_daily_scope WHERE flow=N''purchase'' AND product_id=301986 AND supplier_id=13373)<>1 OR (SELECT COUNT(*) FROM dbo.test_purchase_fx_scope WHERE id=1 AND product_id=301986 AND supplier_id=13373)<>1 THROW 51077,''TEST_SUPPLIER_CONTACT_SCOPE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.test_purchase_fx_intents t JOIN dbo.purchase_invoices p ON p.id=t.invoice_id JOIN dbo.supplier_movements m ON m.purchase_invoice_id=p.id WHERE t.status=N''linked'' AND ((p.status=N''draft'' AND m.movement_type=N''purchase_invoice'') OR (p.status=N''finalized'' AND m.movement_type=N''purchase_invoice_cancel''))) THROW 51077,''TEST_SUPPLIER_CONTACT_POSTING_WINDOW'',1;
IF COALESCE(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.test_supplier_contact_guard''))),2),'''')<>''E7378FD47DA3DBEAC9B1D4DF97ECEDAF7B5E6340DA963F3E62D9D182D4E5BE1A'' OR COALESCE(OBJECTPROPERTY(OBJECT_ID(N''dbo.test_supplier_contact_guard''),''ExecIsTriggerDisabled''),1)<>0 OR COALESCE(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.test_supplier_contact_requests_guard''))),2),'''')<>''B78FAA938A2115FA54D6A15129C00772C8DB9A005CC03F476285FFF1C4D80EE6'' OR COALESCE(OBJECTPROPERTY(OBJECT_ID(N''dbo.test_supplier_contact_requests_guard''),''ExecIsTriggerDisabled''),1)<>0 THROW 51077,''TEST_SUPPLIER_CONTACT_GUARD_DRIFT'',1;
IF @actor_id IS NULL OR @actor_id<>16 OR @request_id IS NULL OR DATALENGTH(@request_id)<>72 OR TRY_CONVERT(uniqueidentifier,@request_id) IS NULL OR CONVERT(varbinary(max),@request_id)<>CONVERT(varbinary(max),LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@request_id)))) OR SUBSTRING(@request_id,15,1) NOT IN(N''1'',N''2'',N''3'',N''4'',N''5'') OR SUBSTRING(@request_id,20,1) NOT IN(N''8'',N''9'',N''a'',N''b'') OR @expected_revision IS NULL OR DATALENGTH(@expected_revision)<>128 OR @expected_revision COLLATE Latin1_General_100_BIN2 LIKE N''%[^0-9A-F]%'' OR @payload_hash IS NULL OR DATALENGTH(@payload_hash)<>128 OR @payload_hash COLLATE Latin1_General_100_BIN2 LIKE N''%[^0-9A-F]%'' OR @payload_json IS NULL OR DATALENGTH(@payload_json)>4096 OR ISJSON(@payload_json)<>1 OR @payload_hash<>CONVERT(char(64),HASHBYTES(''SHA2_256'',@payload_json),2) OR DATALENGTH(@phone)>80 OR DATALENGTH(@city)>200 OR DATALENGTH(@country)>200 OR EXISTS(SELECT 1 FROM (VALUES(@phone),(@city),(@country)) v(value) CROSS JOIN(SELECT TOP(100) ROW_NUMBER() OVER(ORDER BY object_id) n FROM sys.all_objects) pos WHERE pos.n<=DATALENGTH(v.value)/2 AND (UNICODE(SUBSTRING(v.value,pos.n,1)) BETWEEN 0 AND 31 OR UNICODE(SUBSTRING(v.value,pos.n,1))=127)) THROW 51077,''TEST_SUPPLIER_CONTACT_INPUT_INVALID'',1;
-- Same UUID+payload replays the immutable historical response BEFORE CAS.
IF EXISTS(SELECT 1 FROM dbo.test_supplier_contact_requests WHERE request_id=CONVERT(uniqueidentifier,@request_id)) BEGIN
 IF NOT EXISTS(SELECT 1 FROM dbo.test_supplier_contact_requests WHERE request_id=CONVERT(uniqueidentifier,@request_id) AND state=N''completed'' AND actor_id=16 AND payload_hash=@payload_hash AND CONVERT(varbinary(max),payload_json)=CONVERT(varbinary(max),@payload_json)) THROW 51079,''TEST_SUPPLIER_CONTACT_REQUEST_CONFLICT'',1;
